197: func verifyDecisionSource(root string, source Source) error {
198: 	if source.Path == nil || filepath.IsAbs(*source.Path) || filepath.Clean(*source.Path) != *source.Path {
199: 		return &SourceDigestMismatchError{DisplayLabel: source.DisplayLabel, Path: source.Path, ExpectedDigest: source.Digest}
200: 	}
201: 	path := filepath.Join(root, filepath.FromSlash(*source.Path))
202: 	relative, err := filepath.Rel(root, path)
203: 	if err != nil || relative == ".." || strings.HasPrefix(relative, ".."+string(filepath.Separator)) {
204: 		return &SourceDigestMismatchError{DisplayLabel: source.DisplayLabel, Path: source.Path, ExpectedDigest: source.Digest}
205: 	}
206: 	payload, err := os.ReadFile(path)
207: 	if err != nil {
208: 		return &SourceDigestMismatchError{DisplayLabel: source.DisplayLabel, Path: source.Path, ExpectedDigest: source.Digest}
209: 	}
210: 	sum := sha256.Sum256(payload)
211: 	observed := "sha256:" + hex.EncodeToString(sum[:])
212: 	if observed != source.Digest {
213: 		return &SourceDigestMismatchError{DisplayLabel: source.DisplayLabel, Path: source.Path, ExpectedDigest: source.Digest, ObservedDigest: &observed}
214: 	}
215: 	return nil

